using System.Runtime.CompilerServices;
using Miniscuplter.Core;

internal static class LocalDevSaveDestinationTests
{
    [ModuleInitializer]
    internal static void Run()
    {
        var store = new ProjectStore();
        var state = new ProjectState(new ProjectId(Guid.NewGuid()), "Save validation");
        var cancelled = new CancellationToken(true);
        foreach (string? path in new string?[] { null, "", " ", "\t\r\n", "model.txt", "model", "model.msculpt" })
        {
            try { store.SaveAsync(state, path!, cancelled).GetAwaiter().GetResult(); }
            catch (ArgumentException error) when (error.ParamName == "projectPath") { continue; }
            catch (Exception error) { throw new Exception("LD_FAIL_20260919_1003: invalid path reached cancellation or wrong exception", error); }
            throw new Exception("LD_FAIL_20260919_1003: invalid path accepted");
        }
        string root = Path.Combine(Path.GetTempPath(), "localdev-save-" + Guid.NewGuid().ToString("N"));
        try
        {
            foreach (string name in new[] { "lower.msculpt2", "upper.MSCULPT2" })
            {
                string path = Path.Combine(root, name);
                store.SaveAsync(state, path).GetAwaiter().GetResult();
                if (!File.Exists(path))
                    throw new Exception("LD_FAIL_20260919_1003: valid save failed");
            }
        }
        finally { if (Directory.Exists(root)) Directory.Delete(root, true); }
        Console.WriteLine("LD_PASS_20260919_1003");
    }
}
